import { MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, smoothstep, time, uniform, color } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;

  // ──────────────────────────────────────────────────────────────────
  // 1. ROOT GROUP & STAGE BACKDROP
  // ──────────────────────────────────────────────────────────────────
  const root = new THREE.Group();
  root.userData.handlers = {};
  const cleanups = [];

  // Stage backdrop plane (7x6 units at z=-2.5) with vertical gradient
  const backdropGeo = new THREE.PlaneGeometry(7, 6);
  const gradStops = config.intent?.visualSpec?.colors?.gradientStops || [
    { at: 0, hex: '#ff4450' },
    { at: 1, hex: '#c1121f' }
  ];

  // Build gradient from stops: #ff4450 (top, at=0) to #c1121f (bottom, at=1)
  const col1 = new THREE.Color(gradStops[0]?.hex || '#ff4450');
  const col2 = new THREE.Color(gradStops[1]?.hex || '#c1121f');

  const backdropMat = new MeshBasicNodeMaterial({
    colorNode: mix(color(col1), color(col2), smoothstep(0, 1, uv().y))
  });
  const backdrop = new THREE.Mesh(backdropGeo, backdropMat);
  backdrop.position.z = -2.5;
  root.add(backdrop);

  // ──────────────────────────────────────────────────────────────────
  // 2. MAIN CARD (2.4w x 3.2h scene units)
  // ──────────────────────────────────────────────────────────────────
  const cardGroup = new THREE.Group();
  root.add(cardGroup);

  // Card background plane: 2.4 x 3.2, color #16161d
  const cardGeo = new THREE.PlaneGeometry(2.4, 3.2);
  const cardMat = new THREE.MeshBasicNodeMaterial({
    color: 0x16161d
  });
  const cardPlane = new THREE.Mesh(cardGeo, cardMat);
  cardGroup.add(cardPlane);

  // Hairline border: thin black ring around card edge
  // We'll add a slight outline using a line geometry at the perimeter
  const borderGeo = new THREE.BufferGeometry();
  const w = 2.4 / 2;
  const h = 3.2 / 2;
  const pts = [
    new THREE.Vector3(-w, -h, 0.001),
    new THREE.Vector3(w, -h, 0.001),
    new THREE.Vector3(w, h, 0.001),
    new THREE.Vector3(-w, h, 0.001),
    new THREE.Vector3(-w, -h, 0.001)
  ];
  borderGeo.setFromPoints(pts);
  const borderMat = new THREE.LineBasicMaterial({ color: 0x2a2a33, linewidth: 1 });
  const borderLine = new THREE.Line(borderGeo, borderMat);
  cardGroup.add(borderLine);
  cleanups.push(() => borderGeo.dispose());

  // ──────────────────────────────────────────────────────────────────
  // 3. MACHINED HEADER STRIP (top edge)
  // ──────────────────────────────────────────────────────────────────
  const headerGeo = new THREE.PlaneGeometry(2.4, 0.08);
  const headerMat = new MeshStandardNodeMaterial({
    color: 0x16161d,
    roughness: 0.55,
    metalness: 0.5,
    clearcoat: 0.2,
    side: THREE.DoubleSide
  });
  const header = new THREE.Mesh(headerGeo, headerMat);
  header.position.z = 0.002;
  header.position.y = 3.2 / 2 - 0.08 / 2;
  cardGroup.add(header);

  // ──────────────────────────────────────────────────────────────────
  // 4. TEXT CONTENT LAYOUT (interior padding 0.5 units)
  // ──────────────────────────────────────────────────────────────────
  const padding = 0.5;
  const contentStartY = 3.2 / 2 - padding - 0.08; // Below header
  let currentY = contentStartY;

  // 4a. Tier name "ATELIER RESERVE"
  const tierText = ctx.fontAtlas.createText('ATELIER RESERVE', {
    fontSize: 20,
    color: '#e8ecf2',
    align: 'left',
    letterSpacingPx: 20 * 0.08
  });
  tierText.position.set(-2.4 / 2 + padding, currentY - 0.15, 0.003);
  cardGroup.add(tierText);
  currentY -= 0.35;

  // 4b. Price figure "$480" (62px) + caption "PER MONTH, BILLED ANNUALLY" (9px)
  const priceText = ctx.fontAtlas.createText('$480', {
    fontSize: 62,
    color: '#e8ecf2',
    align: 'left'
  });
  priceText.position.set(-2.4 / 2 + padding, currentY - 0.35, 0.003);
  cardGroup.add(priceText);

  const captionText = ctx.fontAtlas.createText('PER MONTH, BILLED ANNUALLY', {
    fontSize: 9,
    color: '#e8ecf2',
    align: 'left',
    letterSpacingPx: 9 * 0.12
  });
  captionText.position.set(-2.4 / 2 + padding, currentY - 0.55, 0.003);
  cardGroup.add(captionText);
  currentY -= 0.8;

  // 4c. Feature rows (0.5-unit gap, then 4 features at 0.375h each)
  currentY -= 0.5;
  const features = [
    'Quarterly movement service',
    'Priority commission slots',
    'Private fitting lounge access',
    'Lifetime case refinishing'
  ];
  const featureTexts = [];
  features.forEach((feat, idx) => {
    const ftext = ctx.fontAtlas.createText(feat, {
      fontSize: 13,
      color: '#e8ecf2',
      align: 'left'
    });
    ftext.position.set(-2.4 / 2 + padding, currentY, 0.003);
    ftext.userData.featureIndex = idx;
    cardGroup.add(ftext);
    featureTexts.push(ftext);

    // Hairline separator below each feature (except last)
    if (idx < features.length - 1) {
      const sepGeo = new THREE.BufferGeometry();
      const sepPts = [
        new THREE.Vector3(-2.4 / 2 + padding, currentY - 0.2, 0.0015),
        new THREE.Vector3(2.4 / 2 - padding, currentY - 0.2, 0.0015)
      ];
      sepGeo.setFromPoints(sepPts);
      const sepMat = new THREE.LineBasicMaterial({ color: 0x23232b, linewidth: 1 });
      const sepLine = new THREE.Line(sepGeo, sepMat);
      cardGroup.add(sepLine);
      cleanups.push(() => sepGeo.dispose());
    }

    currentY -= 0.375;
  });

  // ──────────────────────────────────────────────────────────────────
  // 5. CTA ROW (accent gradient button)
  // ──────────────────────────────────────────────────────────────────
  const ctaGeo = new THREE.PlaneGeometry(1.4, 0.36);
  const ctaMat = new MeshBasicNodeMaterial({
    colorNode: mix(color(col1), color(col2), smoothstep(0, 1, uv().y))
  });
  const ctaButton = new THREE.Mesh(ctaGeo, ctaMat);
  ctaButton.position.z = 0.004;
  ctaButton.position.y = -3.2 / 2 + padding + 0.36 / 2;
  cardGroup.add(ctaButton);

  // CTA emissive rim light (intensity 1.5)
  const ctaRimLight = new THREE.PointLight(0xff2a38, 1.5, 2);
  ctaRimLight.position.copy(ctaButton.position);
  ctaRimLight.position.z = 0.3;
  cardGroup.add(ctaRimLight);

  // CTA label "JOIN THE RESERVE"
  const ctaLabel = ctx.fontAtlas.createText('JOIN THE RESERVE', {
    fontSize: 13,
    color: '#16161d',
    align: 'center',
    letterSpacingPx: 13 * 0.08
  });
  ctaLabel.position.copy(ctaButton.position);
  ctaLabel.position.z = 0.005;
  cardGroup.add(ctaLabel);

  // Store CTA for interaction
  ctaButton.userData.label = ctaLabel;

  // ──────────────────────────────────────────────────────────────────
  // 6. WEIGHTED-SETTLE ENTRANCE ANIMATION
  // ──────────────────────────────────────────────────────────────────
  cardGroup.scale.set(1.04, 1.04, 1);

  const settleTimeline = gsap.timeline({ paused: false });
  settleTimeline.to(
    cardGroup.scale,
    {
      x: 1.0,
      y: 1.0,
      duration: 0.9,
      ease: 'power4.out',
      overwrite: false
    },
    0
  );
  cleanups.push(() => settleTimeline.kill());

  // Feature rows: stagger fade-up (opacity 0->1, y +0.2->0) over 500ms, 80ms stagger
  featureTexts.forEach((ftext, idx) => {
    const initY = ftext.position.y;
    ftext.position.y += 0.2;
    ftext.material.transparent = true;
    ftext.material.opacity = 0;

    gsap.to(
      ftext.position,
      {
        y: initY,
        duration: 0.5,
        ease: 'power2.out',
        delay: 0.1 + idx * 0.08,
        overwrite: false
      }
    );
    gsap.to(
      ftext.material,
      {
        opacity: 1,
        duration: 0.5,
        ease: 'power2.out',
        delay: 0.1 + idx * 0.08,
        overwrite: false
      }
    );
  });

  // ──────────────────────────────────────────────────────────────────
  // 7. CTA PRESS INTERACTION
  // ──────────────────────────────────────────────────────────────────
  let ctaPressTimeline = null;

  const handleCtaMouseDown = () => {
    if (ctaPressTimeline) ctaPressTimeline.kill();
    ctaPressTimeline = gsap.timeline();
    ctaPressTimeline.to(
      ctaButton.scale,
      {
        x: 0.97,
        y: 0.97,
        duration: 0.12,
        ease: 'back.out',
        overwrite: false
      },
      0
    );
  };

  const handleCtaMouseUp = () => {
    if (ctaPressTimeline) ctaPressTimeline.kill();
    ctaPressTimeline = gsap.timeline();
    ctaPressTimeline.to(
      ctaButton.scale,
      {
        x: 1.0,
        y: 1.0,
        duration: 0.2,
        ease: 'power2.out',
        overwrite: false
      },
      0
    );
  };

  root.userData.handlers.onCtaMouseDown = handleCtaMouseDown;
  root.userData.handlers.onCtaMouseUp = handleCtaMouseUp;

  // ──────────────────────────────────────────────────────────────────
  // 8. CLEANUP
  // ──────────────────────────────────────────────────────────────────
  root.userData.cleanup = () => {
    if (ctaPressTimeline) ctaPressTimeline.kill();
    cleanups.forEach((fn) => fn());
    backdropGeo.dispose();
    cardGeo.dispose();
    headerGeo.dispose();
    ctaGeo.dispose();
    backdropMat.dispose();
    cardMat.dispose();
    headerMat.dispose();
    ctaMat.dispose();
    borderMat.dispose();
  };

  return root;
}
